# Guarderia (the day care of Ruta 5, daycare house, C3, contract 34), 10 x 8, interior. column = i, row = j; (0,0) = back corner. A warm little house: nap beds, flowerbeds, a
# bookshelf, the day-care lady (`cuidadora`). Her script is the model of contract 32.7: leave ONE creature (it gains exp while the hero walks), take it back for 100 + 100 / level.
@map guarderia
@size 10 8
@interior yes
@bg 3
@fill floor_wood
@spawn door 4 6 N
@var gd_occ 5                   # daycare_query fills gd_occ, gd_sp, gd_lv (consecutive)
@var gd_sp 6
@var gd_lv 7
@var gd_res 8
@legend
  .  tile=floor_wood
  C  tile=none object=wall_corner
  w  tile=none object=wall_j
  y  tile=none object=wall_win_j
  |  tile=none object=wall_i
  q  tile=none object=wall_win_i
  B  object=bookshelf interact=look text=guarderia.books
  b  object=bed interact=look text=guarderia.bed
  T  object=table interact=look text=guarderia.table
  x  object=flowerbed
  L  npc=cuidadora id=lady face=S script=lady
  m  tile=mat
@grid
  Cwywwwywww
  |.B.....b.
  |...L.T.b.
  q.........
  |.x.......
  |.......x.
  |.........
  |...mm....
@warp m -> ruta_5 spawn=dc_door
@script lady npc
    daycare_query gd_occ      # gd_occ, gd_sp, gd_lv + {v1} the fee, {v2} the levels gained
    name_var 0 gd_sp          # {v0} = the species in care
    npc_face_hero lady
    say guarderia.hello
    jv gd_occ 1 occupied
    ask guarderia.ask_leave
    jv 0 1 leave
    say guarderia.no
    end
  leave:
    daycare_deposit gd_res
    jv gd_res 255 bye
    jv gd_res 0 last
    say guarderia.taken
    end
  last:
    say guarderia.last
    end
  bye:
    say guarderia.no
    end
  occupied:
    ask guarderia.report
    jv 0 1 take
    say guarderia.no
    end
  take:
    daycare_withdraw gd_res
    jv gd_res 1 gave
    jv gd_res 2 poor
    say guarderia.full
    end
  gave:
    say guarderia.back
    end
  poor:
    say guarderia.poor
@end
